drills.solution:
export function bindAll(obj, ...names) {
  for (const name of names) {
    if (typeof obj[name] !== 'function') throw new TypeError(`${name} is not a function`);
    obj[name] = obj[name].bind(obj);
  }
  return obj;
}

tests.code:
assert.equal(typeof mod.bindAll, 'function', 'export bindAll');
const view = { state: 'ready', onClick() { return this.state; } };
mod.bindAll(view, 'onClick');
const h = view.onClick;
assert.equal(h(), 'ready');

const o = { v: 2, a() { return this.v; }, b() { return this.v * 10; } };
assert.equal(mod.bindAll(o, 'a', 'b'), o);
const { a, b } = o;
assert.equal(a() + b(), 22);

const f = function () { return this; };
const o = { keep: f, other() {} };
mod.bindAll(o, 'other');
assert.equal(o.keep, f);

const f = function () {};
const o = { f };
assert.equal(mod.bindAll(o), o);
assert.equal(o.f, f);

drills.explanation:
Loop over the names, check the type, and assign the bound copy back onto the object:

```js
for (const name of names) {
  if (typeof obj[name] !== 'function') throw new TypeError(`${name} is not a function`);
  obj[name] = obj[name].bind(obj);
}
return obj;
```

`bind` returns a new function and leaves the property alone, so calling `obj[name].bind(obj)` without storing the result fails the test "a bound method keeps this when extracted". A wrapper such as `obj[name] = (...args) => obj[name](...args)` does not work either: it reads `obj[name]` at call time, finds itself, and recurses until the stack overflows. Assigning the bound function as an OWN property shadows the prototype method, so it works for class instances too. The explicit type check gives a clear message; `bind` on a non-function would throw a TypeError of its own.

